func (c *Core) choptrOpenImpl(sp *CHOPTRStream, inHigh, inLow, inClose []float64, startIdx, optInTimePeriod int32, outBegIdx, outNBElement *int32, outReal []float64, outStride int32) RetCode {
	var today int32
	var outIdx int32
	var lookbackTotal int32
	var i int32
	var highest float64
	var lowest float64
	var sumTR float64
	var logPeriod float64
	var tempHT float64
	var tempLT float64
	var prevClose float64
	var trueHigh float64
	var trueLow float64
	if len(inHigh) > IndexMax+1 {
		return OutOfRangeEndIndex
	}
	historyLen := int32(len(inHigh))
	endIdx := historyLen - 1
	if len(inLow) != len(inHigh) || len(inClose) != len(inHigh) {
		return BadParam
	}
	if optInTimePeriod == IntegerDefault {
		optInTimePeriod = 14
	} else if optInTimePeriod < 2 || optInTimePeriod > 100000 {
		return BadParam
	}
	if startIdx >= historyLen {
		*outBegIdx = 0
		*outNBElement = 0
		return InsufficientHistory
	}
	*outBegIdx = 0
	*outNBElement = 0
	lookbackTotal = c.choptrLookback(optInTimePeriod)
	if startIdx < lookbackTotal {
		startIdx = lookbackTotal
	}
	if startIdx > endIdx {
		return InsufficientHistory
	}
	logPeriod = math.Log10(float64(optInTimePeriod))
	outIdx = 0
	today = startIdx
	for today <= endIdx {
		highest = inHigh[today]
		lowest = inLow[today]
		sumTR = 0.0
		prevClose = 0.0
		for i = optInTimePeriod; i >= 0; i -= 1 {
			if i < optInTimePeriod {
				tempHT = inHigh[today-i]
				tempLT = inLow[today-i]
				trueHigh = tempHT
				if prevClose > trueHigh {
					trueHigh = prevClose
				}
				trueLow = tempLT
				if prevClose < trueLow {
					trueLow = prevClose
				}
				sumTR += trueHigh - trueLow
				if trueHigh > highest {
					highest = trueHigh
				}
				if trueLow < lowest {
					lowest = trueLow
				}
			}
			prevClose = inClose[today-i]
		}
		if sumTR <= 0.0 {
			outReal[outIdx*outStride] = 100.0
		} else {
			outReal[outIdx*outStride] = float64(100.0 * (math.Log10(sumTR/(highest-lowest)) / logPeriod))
		}
		outIdx += 1
		today += 1
	}
	*outBegIdx = startIdx
	*outNBElement = outIdx
	cap_i := optInTimePeriod + 1
	if cap_i < 1 || cap_i > historyLen {
		return InternalError
	}
	capWin_i_inHigh := make([]float64, cap_i)
	copy(capWin_i_inHigh, inHigh[historyLen-cap_i:historyLen])
	capWin_i_inLow := make([]float64, cap_i)
	copy(capWin_i_inLow, inLow[historyLen-cap_i:historyLen])
	capWin_i_inClose := make([]float64, cap_i)
	copy(capWin_i_inClose, inClose[historyLen-cap_i:historyLen])
	sp.optInTimePeriod = optInTimePeriod
	sp.logPeriod = logPeriod
	sp.winPos_i = 0
	sp.winCap_i = cap_i
	sp.win_i_inHigh = capWin_i_inHigh
	sp.win_i_inLow = capWin_i_inLow
	sp.win_i_inClose = capWin_i_inClose
	sp.cur_outReal = outReal[(*outNBElement-1)*outStride]
	return Success
}

